import { useState, useEffect, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { 
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Checkbox } from '@/components/ui/checkbox';
import { 
  Search, 
  Filter, 
  X, 
  SortAsc, 
  SortDesc,
  Calendar,
  DollarSign,
  Users,
  Target,
  RefreshCw,
  Download,
  Eye,
  Settings
} from 'lucide-react';

const FILTER_CATEGORIES = {
  status: {
    label: 'الحالة',
    options: ['مكتملة', 'قيد التنفيذ', 'متأخرة', 'لم تبدأ']
  },
  completion: {
    label: 'نسبة الإكمال',
    options: ['0-25%', '26-50%', '51-75%', '76-100%']
  },
  budget: {
    label: 'الميزانية',
    options: ['أقل من 50,000', '50,000-100,000', '100,000-500,000', 'أكثر من 500,000']
  },
  priority: {
    label: 'الأولوية',
    options: ['عالية', 'متوسطة', 'منخفضة']
  }
};

const SORT_OPTIONS = [
  { value: 'name_asc', label: 'الاسم (أ-ي)', field: 'name', direction: 'asc' },
  { value: 'name_desc', label: 'الاسم (ي-أ)', field: 'name', direction: 'desc' },
  { value: 'completion_desc', label: 'نسبة الإكمال (عالي-منخفض)', field: 'completion_percentage', direction: 'desc' },
  { value: 'completion_asc', label: 'نسبة الإكمال (منخفض-عالي)', field: 'completion_percentage', direction: 'asc' },
  { value: 'budget_desc', label: 'الميزانية (عالي-منخفض)', field: 'planned_budget', direction: 'desc' },
  { value: 'budget_asc', label: 'الميزانية (منخفض-عالي)', field: 'planned_budget', direction: 'asc' },
  { value: 'date_desc', label: 'تاريخ الإنشاء (الأحدث)', field: 'created_at', direction: 'desc' },
  { value: 'date_asc', label: 'تاريخ الإنشاء (الأقدم)', field: 'created_at', direction: 'asc' }
];

function AdvancedSearch({ 
  data = [], 
  onFilteredData, 
  placeholder = "البحث في المبادرات...",
  searchFields = ['name', 'description', 'responsible_person', 'department'],
  showAdvancedFilters = true 
}) {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedFilters, setSelectedFilters] = useState({});
  const [sortBy, setSortBy] = useState('date_desc');
  const [showFilters, setShowFilters] = useState(false);
  const [savedSearches, setSavedSearches] = useState([]);
  const [searchName, setSearchName] = useState('');

  // Advanced search logic
  const filteredAndSortedData = useMemo(() => {
    let filtered = [...data];

    // Text search
    if (searchTerm.trim()) {
      const searchLower = searchTerm.toLowerCase().trim();
      filtered = filtered.filter(item => 
        searchFields.some(field => {
          const value = item[field];
          return value && value.toString().toLowerCase().includes(searchLower);
        })
      );
    }

    // Apply filters
    Object.entries(selectedFilters).forEach(([category, values]) => {
      if (values && values.length > 0) {
        filtered = filtered.filter(item => {
          switch (category) {
            case 'status':
              return values.includes(item.status);
            
            case 'completion':
              const completion = item.completion_percentage || 0;
              return values.some(range => {
                switch (range) {
                  case '0-25%': return completion >= 0 && completion <= 25;
                  case '26-50%': return completion >= 26 && completion <= 50;
                  case '51-75%': return completion >= 51 && completion <= 75;
                  case '76-100%': return completion >= 76 && completion <= 100;
                  default: return false;
                }
              });
            
            case 'budget':
              const budget = item.planned_budget || 0;
              return values.some(range => {
                switch (range) {
                  case 'أقل من 50,000': return budget < 50000;
                  case '50,000-100,000': return budget >= 50000 && budget <= 100000;
                  case '100,000-500,000': return budget >= 100000 && budget <= 500000;
                  case 'أكثر من 500,000': return budget > 500000;
                  default: return false;
                }
              });
            
            case 'priority':
              return values.includes(item.priority || 'متوسطة');
            
            default:
              return true;
          }
        });
      }
    });

    // Apply sorting
    const sortOption = SORT_OPTIONS.find(opt => opt.value === sortBy);
    if (sortOption) {
      filtered.sort((a, b) => {
        const aValue = a[sortOption.field] || '';
        const bValue = b[sortOption.field] || '';
        
        let comparison = 0;
        if (typeof aValue === 'string') {
          comparison = aValue.localeCompare(bValue, 'ar');
        } else {
          comparison = aValue - bValue;
        }
        
        return sortOption.direction === 'desc' ? -comparison : comparison;
      });
    }

    return filtered;
  }, [data, searchTerm, selectedFilters, sortBy, searchFields]);

  // Update parent component with filtered data
  useEffect(() => {
    onFilteredData?.(filteredAndSortedData);
  }, [filteredAndSortedData, onFilteredData]);

  const handleFilterChange = (category, option, checked) => {
    setSelectedFilters(prev => {
      const categoryFilters = prev[category] || [];
      if (checked) {
        return {
          ...prev,
          [category]: [...categoryFilters, option]
        };
      } else {
        return {
          ...prev,
          [category]: categoryFilters.filter(item => item !== option)
        };
      }
    });
  };

  const clearAllFilters = () => {
    setSearchTerm('');
    setSelectedFilters({});
    setSortBy('date_desc');
  };

  const saveCurrentSearch = () => {
    if (!searchName.trim()) return;
    
    const searchConfig = {
      id: Date.now(),
      name: searchName,
      searchTerm,
      filters: selectedFilters,
      sortBy,
      createdAt: new Date().toISOString()
    };
    
    setSavedSearches(prev => [...prev, searchConfig]);
    setSearchName('');
  };

  const loadSavedSearch = (searchConfig) => {
    setSearchTerm(searchConfig.searchTerm);
    setSelectedFilters(searchConfig.filters);
    setSortBy(searchConfig.sortBy);
  };

  const deleteSavedSearch = (searchId) => {
    setSavedSearches(prev => prev.filter(search => search.id !== searchId));
  };

  const getActiveFiltersCount = () => {
    return Object.values(selectedFilters).reduce((count, filters) => 
      count + (filters?.length || 0), 0
    );
  };

  const exportFilteredData = () => {
    // This would integrate with the existing export functionality
    console.log('Exporting filtered data:', filteredAndSortedData);
  };

  return (
    <div className="space-y-4">
      {/* Main Search Bar */}
      <Card>
        <CardContent className="p-4">
          <div className="flex items-center gap-4">
            <div className="relative flex-1">
              <Search className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
              <Input
                placeholder={placeholder}
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pr-10"
              />
            </div>
            
            <Select value={sortBy} onValueChange={setSortBy}>
              <SelectTrigger className="w-48">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {SORT_OPTIONS.map(option => (
                  <SelectItem key={option.value} value={option.value}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            {showAdvancedFilters && (
              <Button
                variant="outline"
                onClick={() => setShowFilters(!showFilters)}
                className={`${showFilters ? 'bg-orange-50 border-orange-200' : ''}`}
              >
                <Filter className="h-4 w-4 ml-2" />
                فلترة
                {getActiveFiltersCount() > 0 && (
                  <Badge className="mr-2 bg-orange-600 text-white">
                    {getActiveFiltersCount()}
                  </Badge>
                )}
              </Button>
            )}

            <Button
              variant="outline"
              onClick={clearAllFilters}
              disabled={!searchTerm && getActiveFiltersCount() === 0}
            >
              <RefreshCw className="h-4 w-4 ml-2" />
              مسح
            </Button>

            <Button
              variant="outline"
              onClick={exportFilteredData}
              disabled={filteredAndSortedData.length === 0}
            >
              <Download className="h-4 w-4 ml-2" />
              تصدير
            </Button>
          </div>

          {/* Active Filters Display */}
          {(searchTerm || getActiveFiltersCount() > 0) && (
            <div className="flex flex-wrap items-center gap-2 mt-3 pt-3 border-t border-gray-200">
              <span className="text-sm text-gray-600">الفلاتر النشطة:</span>
              
              {searchTerm && (
                <Badge variant="outline" className="bg-blue-50 border-blue-200">
                  البحث: "{searchTerm}"
                  <X 
                    className="h-3 w-3 mr-1 cursor-pointer" 
                    onClick={() => setSearchTerm('')}
                  />
                </Badge>
              )}

              {Object.entries(selectedFilters).map(([category, values]) =>
                values?.map(value => (
                  <Badge key={`${category}-${value}`} variant="outline" className="bg-orange-50 border-orange-200">
                    {FILTER_CATEGORIES[category]?.label}: {value}
                    <X 
                      className="h-3 w-3 mr-1 cursor-pointer" 
                      onClick={() => handleFilterChange(category, value, false)}
                    />
                  </Badge>
                ))
              )}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Advanced Filters Panel */}
      <AnimatePresence>
        {showFilters && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.3 }}
          >
            <Card>
              <CardHeader>
                <CardTitle className="text-orange-600 flex items-center gap-2">
                  <Settings className="h-5 w-5" />
                  فلاتر متقدمة
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                  {Object.entries(FILTER_CATEGORIES).map(([category, config]) => (
                    <div key={category}>
                      <h4 className="font-medium text-gray-900 mb-3">{config.label}</h4>
                      <div className="space-y-2">
                        {config.options.map(option => (
                          <div key={option} className="flex items-center space-x-2 space-x-reverse">
                            <Checkbox
                              id={`${category}-${option}`}
                              checked={selectedFilters[category]?.includes(option) || false}
                              onCheckedChange={(checked) => 
                                handleFilterChange(category, option, checked)
                              }
                            />
                            <label 
                              htmlFor={`${category}-${option}`}
                              className="text-sm text-gray-700 cursor-pointer"
                            >
                              {option}
                            </label>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>

                {/* Save Search */}
                <div className="mt-6 pt-6 border-t border-gray-200">
                  <div className="flex items-center gap-4">
                    <Input
                      placeholder="اسم البحث المحفوظ..."
                      value={searchName}
                      onChange={(e) => setSearchName(e.target.value)}
                      className="max-w-xs"
                    />
                    <Button
                      onClick={saveCurrentSearch}
                      disabled={!searchName.trim()}
                      size="sm"
                    >
                      حفظ البحث
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Saved Searches */}
      {savedSearches.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="text-orange-600">عمليات البحث المحفوظة</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex flex-wrap gap-2">
              {savedSearches.map(search => (
                <div key={search.id} className="flex items-center gap-2 p-2 bg-gray-50 rounded-lg">
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => loadSavedSearch(search)}
                    className="text-sm"
                  >
                    <Eye className="h-3 w-3 ml-1" />
                    {search.name}
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => deleteSavedSearch(search.id)}
                    className="text-red-600 hover:text-red-700 p-1"
                  >
                    <X className="h-3 w-3" />
                  </Button>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Results Summary */}
      <div className="flex items-center justify-between text-sm text-gray-600">
        <span>
          عرض {filteredAndSortedData.length} من أصل {data.length} عنصر
        </span>
        {filteredAndSortedData.length !== data.length && (
          <span className="text-orange-600">
            تم تطبيق {getActiveFiltersCount() + (searchTerm ? 1 : 0)} فلتر
          </span>
        )}
      </div>
    </div>
  );
}

export default AdvancedSearch;
